import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph User + Dev Monthly Meetup - May 2026","description":"","frontmatter":{"title":"Ceph User + Dev Monthly Meetup - May 2026","date":"2026-05-27T00:00:00.000Z","updated":"2026-05-27T00:00:00.000Z","tags":["Ceph","dashboard","NVMe over TCP","bluestore","OSD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_User_+_Dev_Monthly_Meetup_-_May_2026.md","filePath":"posts/2026/Ceph_User_+_Dev_Monthly_Meetup_-_May_2026.md","lastUpdated":1780459816000}'),l={name:"posts/2026/Ceph_User_+_Dev_Monthly_Meetup_-_May_2026.md"};function i(n,e,s,h,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 Ceph 用户与开发者月度例会于 2026 年 5 月举行，涵盖 dashboard 新功能展示、VMware vSphere 与 NVMe TCP 集成问题讨论、Crimson 项目进展询问，以及异构磁盘集群使用经验分享等多个议题。</p><h2 id="一、dashboard-概览页面展示" tabindex="-1">一、Dashboard 概览页面展示 <a class="header-anchor" href="#一、dashboard-概览页面展示" aria-label="Permalink to &quot;一、Dashboard 概览页面展示&quot;">​</a></h2><h3 id="初始集群视图" tabindex="-1">初始集群视图 <a class="header-anchor" href="#初始集群视图" aria-label="Permalink to &quot;初始集群视图&quot;">​</a></h3><p>演讲者 Afne 展示了 Ceph dashboard 的全新 onboarding 页面。当集群通过 <code>cephadm</code> 完成 bootstrap 后，页面会显示欢迎信息并提示最低配置要求，引导用户决定是否跳过存储配置流程直接进入集群概览页。</p><p>初始集群状态展示要点：</p><ul><li><strong>数据弹性（Data Resiliency）</strong>：所有 PG 均处于 active clean 状态，465 个 placement groups 全部健康，数据完全复制可用</li><li><strong>系统状态（Systems Tab）</strong>：MON 正常运行，但仅有一个 active manager，无 standby manager，dashboard 对此发出警告</li><li><strong>OSD 状态</strong>：所有 OSD 均处于 in/up 状态，所有节点可用，无活跃告警</li><li><strong>性能数据</strong>：初始状态下 IOPS、延迟和吞吐量数据为空</li></ul><h3 id="成熟集群视图" tabindex="-1">成熟集群视图 <a class="header-anchor" href="#成熟集群视图" aria-label="Permalink to &quot;成熟集群视图&quot;">​</a></h3><p>演讲者切换至一个创建于 5 月 21 日的成熟集群进行对比展示：</p><ul><li><strong>消费趋势卡片（Consumption Trend）</strong>：仅在有足够用户数据时显示，提供存储填满时间的粗略估算（约 7 小时），以及每日平均消费量（约 70 GB/天）</li><li><strong>性能图表</strong>：支持按时间跨度（最近几天/30 天）查看，可独立切换读/写 IOPS 及读/写吞吐量的显示</li><li><strong>存储分解视图</strong>：展示 raw capacity 的详细分布，包含 block pools和 object storage buckets 的占用情况</li><li><strong>告警系统</strong>：展示了多个严重告警，包括 module crash需要排查</li></ul><h3 id="故障模拟演示" tabindex="-1">故障模拟演示 <a class="header-anchor" href="#故障模拟演示" aria-label="Permalink to &quot;故障模拟演示&quot;">​</a></h3><p>演讲者通过以下操作模拟集群异常状态：</p><ul><li>手动将一个 OSD 标记为 down，触发 PG 状态变化</li><li>调低 near full ratio阈值，触发高存储使用率告警</li><li>展示 data resiliency 指标的实时响应：active clean PG 百分比降至 0，超过半数 PG 进入 degraded 状态，部分 PG 处于 undersized 状态</li><li>一个节点离线，一个 MON 退出 quorum，6 个 OSD 中仅 4 个处于 in/up 状态</li></ul><p>dashboard 能够实时捕捉集群状态变化，响应速度较快。</p><h2 id="二、vmware-vsphere-7-8-与-nvme-tcp-集成问题" tabindex="-1">二、VMware vSphere 7/8 与 NVMe TCP 集成问题 <a class="header-anchor" href="#二、vmware-vsphere-7-8-与-nvme-tcp-集成问题" aria-label="Permalink to &quot;二、VMware vSphere 7/8 与 NVMe TCP 集成问题&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>社区新成员 Zoha 正在对 VMware vSphere 环境下 Ceph 的 NVMe over TCP（block storage）进行 benchmarking，整体性能结果良好，但存在稳定性问题。</p><h3 id="问题一-ntp-时间同步" tabindex="-1">问题一：NTP 时间同步 <a class="header-anchor" href="#问题一-ntp-时间同步" aria-label="Permalink to &quot;问题一：NTP 时间同步&quot;">​</a></h3><p><strong>现象</strong>：在超融合平台上，NTP 同步不稳定时会导致 NVMe TCP gateway 频繁崩溃。</p><p><strong>具体经历</strong>：</p><ul><li>使用 chrony 进行时间同步效果不佳</li><li>切换为 Ubuntu 原生 NTP 服务后有所改善，但节点重启后仍出现 NTP 同步问题</li><li>存在明显的时间漂移（time drift）</li></ul><p><strong>社区建议</strong>：</p><ul><li>社区成员 Philip 分享了一种可行方案：指定一台服务器与外部 NTP 服务器同步，其余 Ceph 节点统一指向该服务器，即使其他节点离线也能保持稳定</li><li>Philip 表示愿意分享其 chrony 配置文件，双方约定后续通过 Google Meet 进一步交流</li></ul><h3 id="问题二-vmware-vsphere-full-clone-性能" tabindex="-1">问题二：VMware vSphere Full Clone 性能 <a class="header-anchor" href="#问题二-vmware-vsphere-full-clone-性能" aria-label="Permalink to &quot;问题二：VMware vSphere Full Clone 性能&quot;">​</a></h3><p><strong>现象</strong>：在 VMware 环境中对连接至 Ceph block storage 的虚拟机执行 full clone 操作时，耗时数小时，原因是 clone 操作未被下放（offload）至存储层执行。</p><p><strong>开发进展</strong>：Ceph NVMe 核心开发者 Aviv 在会议中确认：</p><ul><li>vSphere full clone 功能目前正在开发中</li><li>当前实现方式为从一个 datastore 读取并写入另一个 datastore</li><li>预计在未来几个月内完成支持，属于 work in progress</li></ul><p><strong>后续行动</strong>：</p><ul><li>Zoha 将在 Ceph tracker 的 NVMe 项目下创建 issue，并附上相关日志</li><li>Aviv 将跟进该 issue</li></ul><h3 id="社区资源推荐" tabindex="-1">社区资源推荐 <a class="header-anchor" href="#社区资源推荐" aria-label="Permalink to &quot;社区资源推荐&quot;">​</a></h3><ul><li>订阅 <strong>ceph-users 邮件列表</strong>并重新发送问题（首次可能未获足够关注）</li><li>加入 <strong>Ceph Slack</strong> 相关频道</li><li>查阅 <strong>Ceph GitHub</strong> 仓库中 NVMe fabric 相关 commits</li><li>观看 <strong>Ceph Days</strong> 的 YouTube 录像（Mike 和 Aviv 的相关演讲）</li><li>参加每周举行的 NVMe 专项会议</li></ul><h2 id="三、crimson-项目进展询问" tabindex="-1">三、Crimson 项目进展询问 <a class="header-anchor" href="#三、crimson-项目进展询问" aria-label="Permalink to &quot;三、Crimson 项目进展询问&quot;">​</a></h2><p>社区成员询问 Crimson（针对 NVMe 优化的新一代 Ceph OSD 实现）的开发进展。</p><p><strong>回应</strong>：Crimson 项目仍在积极开发中，有专属团队负责推进，最新进展可在 Ceph 官网的 Crimson 项目页面查阅。</p><h2 id="四、nvme-over-tcp-成熟度" tabindex="-1">四、NVMe over TCP 成熟度 <a class="header-anchor" href="#四、nvme-over-tcp-成熟度" aria-label="Permalink to &quot;四、NVMe over TCP 成熟度&quot;">​</a></h2><p>社区成员询问 NVMe over TCP 及 NVMe over RoCE（NVMe-oF）的成熟度。</p><ul><li>Ceph 官方文档中有相关说明</li><li>Zoha 分享了 IBM 提供的 NVMe TCP 配置文档链接（已附于会议 etherpad）</li><li>整体而言，NVMe over TCP 已可用于生产环境，但在特定配置（如 VMware 集成）下仍存在稳定性挑战</li></ul><h2 id="五、异构磁盘集群使用经验" tabindex="-1">五、异构磁盘集群使用经验 <a class="header-anchor" href="#五、异构磁盘集群使用经验" aria-label="Permalink to &quot;五、异构磁盘集群使用经验&quot;">​</a></h2><p>Gregory 提问：在使用不同容量磁盘的异构集群时是否存在明显坑点？</p><p><strong>社区经验分享</strong>：</p><ul><li>异构磁盘集群可以正常运行，但需要关注 <strong>PG 分布不均衡</strong>问题</li><li>容量较小的磁盘可能因 PG 分配比例相同而导致使用率过高</li><li><strong>解决方案</strong>：通过调整 CRUSH weight 进行手动 rebalancing，例如对 1TB 磁盘相对于 4TB 磁盘适当降低权重（<code>ceph osd crush reweight</code>）</li><li>操作并不复杂，整体可控</li></ul><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>负责人</th><th>行动项</th></tr></thead><tbody><tr><td>Zoha</td><td>在 Ceph tracker NVMe 项目下创建 issue，附上 NVMe TCP gateway崩溃日志</td></tr><tr><td>Zoha &amp; Philip</td><td>通过 Google Meet 交流 chrony NTP 配置方案</td></tr><tr><td>Anthony</td><td>本周内通过邮件列表和 Slack 发送会议时间调查问卷</td></tr><tr><td>会议组织者</td><td>将 NVMe tracker 项目链接和 IBM 文档链接更新至 etherpad</td></tr></tbody></table><h2 id="下次会议" tabindex="-1">下次会议 <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议&quot;">​</a></h2><p>下次月度例会将于 2026 年 6 月举行，欢迎持续关注 ceph-users 邮件列表及 Slack 频道获取会议通知。</p>',45)])])}const g=a(l,[["render",i]]);export{u as __pageData,g as default};
